    description = 'This textual convention defines the 802.11E \n                traffic classes:\n                    background(0)        - background traffic,\n                                           lowest priority\n                    bestEffort(1)        - best effort delivery,\n                                           default priority class \n                                           for all traffic\n                    video(2)             - video traffic, 2nd \n                                           highest priority\n                    voice(3)             - voice traffic, highest\n                                           priority.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(0, 1, 2, 3))
    namedValues = NamedValues(("background", 0), ("bestEffort", 1), ("video", 2), ("voice", 3))

